graphql.query:
query IntrospectionQuery {
  __schema {
    queryType { name }
    mutationType { name }
    subscriptionType { name }
    types {
      ...FullType
    }
    directives {
      name
      description
      locations
      args {
        ...InputValue
      }
    }
  }
}

fragment FullType on __Type {
  kind
  name
  description
  fields(includeDeprecated: true) {
    name
    description
    args {
      ...InputValue
    }
    type {
      ...TypeRef
    }
    isDeprecated
    deprecationReason
  }
  inputFields {
    ...InputValue
  }
  interfaces {
    ...TypeRef
  }
  enumValues(includeDeprecated: true) {
    name
    description
    isDeprecated
    deprecationReason
  }
  possibleTypes {
    ...TypeRef
  }
}

fragment InputValue on __InputValue {
  name
  description
  type { ...TypeRef }
  defaultValue
}

fragment TypeRef on __Type {
  kind
  name
  ofType {
    kind
    name
    ofType {
      kind
      name
      ofType {
        kind
        name
        ofType {
          kind
          name
          ofType {
            kind
            name
            ofType {
              kind
              name
              ofType {
                kind
                name
              }
            }
          }
        }
      }
    }
  }
}

query Node($id: ID!) {
  node(id: $id) {
    __typename
    id
    ... on User {
      email
      name
      role
      createdAt
      updatedAt
      legacyToken
      orders {
        id
        status
        totalCents
        createdAt
        updatedAt
        lines {
          quantity
        }
      }
      address {
        line1
        line2
        city
        country
        geo {
          lat
          lng
        }
      }
    }
    ... on Category {
      name
      products {
        totalCount
        edges {
          cursor
        }
        pageInfo {
          hasNextPage
          endCursor
        }
      }
    }
    ... on Product {
      sku
      title
      description
      priceCents
      inStock
      tags
      createdAt
      updatedAt
      attributes
      category {
        id
        name
        products {
          totalCount
        }
      }
      reviews {
        id
        rating
        body
        author {
          id
          email
          name
          role
          createdAt
          updatedAt
          legacyToken
        }
      }
    }
    ... on Order {
      status
      totalCents
      createdAt
      updatedAt
      user {
        id
        email
        name
        role
        createdAt
        updatedAt
        legacyToken
        address {
          line1
          line2
          city
          country
        }
      }
      lines {
        quantity
        product {
          id
          sku
          title
          description
          priceCents
          inStock
          tags
          createdAt
          updatedAt
          attributes
        }
      }
    }
  }
}

